import React, { useState, useEffect } from 'react'
import CommonSection from '../share/CommonSection'
import { Col, Container, Row } from 'reactstrap'
import "../style/tour.css"
import TourCard from '../share/TourCard'
import SearchBar from '../share/SearchBar'
import Newsletter from '../share/Newsletter'

import useFetch from '../hooks/useFetch'
import { BASE_URL } from '../utils/config'

const Tour = () => {

  const [pageCount, setPageCount] = useState(0)
  const [page, setPage] = useState(0)
  
  const {data:tours, loading, error} = useFetch(`${BASE_URL}/tours?page=${page}`)
  const {data:tourCount} = useFetch(`${BASE_URL}/tours/search/getTourCount`)

  useEffect(() => {
    const pages = Math.ceil(tourCount / 8)
    setPageCount(pages)
    window.scrollTo
  }, [page, tourCount])

  return (
    <>
      <CommonSection title={"Tất cả các tour"} />
      <section>
        <Container>
          <Row>
            <SearchBar />
          </Row>
        </Container>
      </section>
      <section className='pt-0'>
        <Container>
          {loading && <h4 className='text-center pt-5'>Loading......</h4>}
          {error && <h4 className='text-center pt-5'>{error}</h4>}

          {
            !loading && !error && <Row>
            {
              tours?.map(tour => <Col lg='3' key={tour._id}><TourCard tour={tour} /></Col>)
            }

            <Col lg='12'>
              <div className="pagination d-flex align-items-center justify-content-center mt-4 gap-3">
                {[...Array(pageCount).keys()].map(number=>(
                  <span key={number} onClick={() => setPage(number)}
                  className={page === number ? 'active_page' : ''}
                  >
                    {number + 1}
                  </span>
                ))}
              </div>
            </Col>
          </Row>
          }
        </Container>
      </section>
      <Newsletter/>
    </>
  )
}

export default Tour
